  const [payerMetadataReady,setPayerMetadataReady]=useState(false);
  const [financeCloudRevision, setFinanceCloudRevision] = useState(0);
  const financeNavRestored=useRef(false);
  const [financeNavReady,setFinanceNavReady]=useState(false);
  const [tab, setTab] = useState<Tab>("summary");
  const [action, setAction] = useState<Action>(null);
  const [voiceText, setVoiceText] = useState("");
  const [voicePreview, setVoicePreview] = useState<VoicePreview | null>(null);
  const [listFilter, setListFilter] = useState<Filter>("ALL");
  const [undoDeletion, setUndoDeletion] = useState<FinanceData | null>(null);
  const [kidsAudit, setKidsAudit] = useState<KidsFinanceAudit | null>(null);
  const [personalAudit, setPersonalAudit] = useState<PersonalFinanceAudit | null>(null);
  const [kidsStudentOptions, setKidsStudentOptions] = useState<Array<{id:string;name:string}>>([]);
  const [mercadoPagoBalance, setMercadoPagoBalance] = useState<number | null>(null);
  const competence = data.currentCompetence;
  useEffect(()=>{
    if(!loaded||financeNavRestored.current)return;
    financeNavRestored.current=true;
    const saved=window.history.state?.dmpFinanceQuery;
    if(saved){
      if(["summary","mercado-pago","personal","ds","expenses","extras","closing","reports"].includes(saved.tab))setTab(saved.tab);
      if(["ALL","PAID","OPEN","OVERDUE"].includes(saved.filter))setListFilter(saved.filter);
      if(typeof saved.competence==="string"&&data.competences[saved.competence])setData(current=>({...current,currentCompetence:saved.competence}));
    }
    setFinanceNavReady(true);
  },[loaded,data]);
  useEffect(()=>{
    if(!financeNavReady)return;
    window.history.replaceState({...window.history.state,dmpFinanceQuery:{tab,filter:listFilter,competence}},"",window.location.href);
  },[financeNavReady,tab,listFilter,competence]);
  const summary = useMemo(() => financeSummary(data, competence), [data, competence]);
  const pendencies = useMemo(() => financialPendencies(data, competence), [data, competence]);
  const editable = isCompetenceEditable(data, competence);
  const competences = useMemo(() => Object.keys(data.competences).sort().reverse(), [data.competences]);
  async function refreshFinanceAfterMercadoPago() {
    try {
      const cloud = await fetchFinanceCloud(financeSeedAugust2026);
      if (!cloud) return;
      const next = ensureCalendarCompetence(cloud);
      setData(next);
      saveFinanceData(next);
      setCloudWritable(true);
    } catch (error) {
      console.error("Financeiro: falha ao recarregar apos conciliacao Mercado Pago.", error);
    }
  }

  useEffect(() => {
    let cancelled = false;
    async function readMercadoPagoBalance() {
      try {
        const response = await fetch("/api/mercado-pago", { cache: "no-store" });
        if (!response.ok) return;
        const payload = await response.json();
        if (cancelled || !payload?.ok) return;
        setMercadoPagoBalance(typeof payload.balance === "number" ? payload.balance : null);
      } catch {
        if (!cancelled) setMercadoPagoBalance(null);
      }
    }
    void readMercadoPagoBalance();
    const timer = window.setInterval(() => { void readMercadoPagoBalance(); }, 5 * 60 * 1000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, []);
  const weeklyDue = useMemo(() => {
    const now=new Date();const day=now.getDay();const monday=new Date(now);monday.setDate(now.getDate()-(day===0?6:day-1));const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);
    const start=localDateISO(monday),end=localDateISO(sunday);
    return summary.expenses.filter(item=>remaining(item.expectedAmount,item.payments)>0).map(item=>({...item,dueDate:dueDateFor(competence,item.dueDay),open:remaining(item.expectedAmount,item.payments)})).filter(item=>item.dueDate>=start&&item.dueDate<=end).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)||a.name.localeCompare(b.name,"pt-BR"));
  },[summary.expenses,competence]);

  useEffect(() => {
    let cancelled = false;

    async function createSafetyBackup() {
      const response = await fetch("/api/backup", { method: "POST" });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok || !payload?.ok) {
        throw new Error("Backup de segurança não foi criado. Migração cancelada.");
      }
      return payload.backup;
    }

    async function putJson(url:string, body:unknown) {
      const response = await fetch(url, {
        method:"PUT",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify(body),
      });
      if (!response.ok) throw new Error(`Falha ao salvar ${url}`);
    }

    async function load() {
      const local = loadFinanceData(financeSeedAugust2026);

      try {
        const cloud = await fetchFinanceCloud(financeSeedAugust2026);
        if (cancelled) return;

        if (!cloud) {
          setData(ensureCalendarCompetence(local));
          setCloudWritable(false);
          return;
        }

        const base = cloud;
        const originalStudents = students.map(student => ({...student}));
        const target = today().slice(0,7);

        // Antes de criar mês novo, somente atualiza a informação de renovação.
        // Valor e vencimento do mês anterior NÃO são recalculados.
        let prepared = base;
        if (!base.competences[target]) {
          const previous = Object.keys(base.competences)
            .filter(value => value < target)
            .sort()
            .at(-1);
          if (previous) {
            prepared = preparePersonalRenewalForNextMonth(
              prepared,
              originalStudents,
              previous,
            ).data;
          }
        }

        let next = ensureCalendarCompetence(prepared);

        // 1) Migra Personal existente: Financeiro atual -> cadastro.
        // 2) A partir daí cadastro -> mensalidade da competência atual.
        const personal = reconcilePersonalFinance(
          next,
          originalStudents,
          next.currentCompetence,
        );
        next = personal.data;
        let nextStudents = personal.students;
        setPersonalAudit(personal.audit);

        // Kids: vincula aliases conhecidos e mantém órfãos fora da soma.
        try {
          const kidsResponse = await fetch("/api/kids", { cache:"no-store" });
          if (kidsResponse.ok) {
            const kidsPayload = await kidsResponse.json();
            if (kidsPayload.data) {
              const kidsData = kidsPayload.data as KidsData;
              const profiles = new Map<string,{id:string;name:string}>();
              for (const group of kidsData.classes) {
                for (const student of group.students) {
                  if (!profiles.has(student.id)) profiles.set(student.id,{id:student.id,name:student.name});
                }
              }
              if (!cancelled) setKidsStudentOptions([...profiles.values()].sort((a,b)=>a.name.localeCompare(b.name,"pt-BR")));
              const reconciled = reconcileKidsFinance(
                next,
                kidsData,
              );
              next = reconciled.data;
              setKidsAudit(reconciled.audit);
            }
          }
        } catch (error) {
          console.error("Financeiro: conferência Kids falhou.", error);
        }

        const studentsChanged =
          JSON.stringify(nextStudents) !== JSON.stringify(originalStudents);
        const financeChanged =
          hasPendingDsOpeningInitialization(base) || JSON.stringify(next) !== JSON.stringify(base);

        if (studentsChanged || financeChanged) {
          // NADA é gravado antes deste backup.
          await createSafetyBackup();

          let studentsSaved = false;
          try {
            if (studentsChanged) {
              await putJson("/api/data", nextStudents);
              studentsSaved = true;
            }
            if (financeChanged) {
              await saveFinanceCloud(next);
            }
          } catch (saveError) {
            // Rollback imediato do cadastro se o Financeiro falhar depois.
            if (studentsSaved) {
              try {
                await putJson("/api/data", originalStudents);
              } catch (rollbackError) {
                console.error("Rollback do cadastro falhou; backup manual disponível.", rollbackError);
              }
            }
            throw saveError;
          }
        }

        if (cancelled) return;

        if (personal.changedStudents) {
          onStudentsChange?.(nextStudents);
        }

        setData(next);
        saveFinanceData(next);
        setCloudWritable(true);
      } catch (error) {
        console.error(
          "Financeiro: migração protegida não foi concluída; usando dados sem migração.",
          error,
        );
        if (!cancelled) {
          setData(local);
          setCloudWritable(false);
          window.alert(
            "A migração financeira foi interrompida por segurança. Nenhum dado foi apagado. Consulte o backup antes de tentar novamente.",
          );
        }
      } finally {
        if (!cancelled) setLoaded(true);
      }
    }

    void load();
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (!loaded) return;
    saveFinanceData(data);
    if (!cloudWritable || payerSaving) return;
    setPayerMetadataReady(false);
    setSyncing(true); // Bloqueia edição de metadados também enquanto uma gravação está agendada.
    const timer = window.setTimeout(() => {
      setSyncing(true);
      void saveFinanceCloud(data)
        .then(() => {setFinanceCloudRevision(current => current + 1);setPayerMetadataReady(true);})
        .catch(error => {
          console.error("Financeiro: erro ao salvar na nuvem.", error);
          if(error instanceof Error&&error.message==="FINANCE_CONFLICT"){
            setCloudWritable(false);
            window.alert("O Financeiro foi alterado em outra aba ou dispositivo. Esta gravação foi bloqueada para proteger os dados. Atualize a página antes de continuar.");
          }
        })
        .finally(() => setSyncing(false));
    }, 450);
    return () => window.clearTimeout(timer);
  }, [data, loaded, cloudWritable, payerSaving]);

  function dispatch(command: FinanceCommand) {
    if(command.type.endsWith("_DELETE"))setUndoDeletion(data);
    setData(current => applyFinanceCommand(current, command));
  }

  function undoLastDeletion(){if(!undoDeletion)return;setData(undoDeletion);setUndoDeletion(null);}

  function requireEditable() {
    if (editable) return true;
    window.alert("Esta competência está fechada. Reabra o mês na aba Fechamento para alterar dados.");
    return false;
  }

  function openAction(next: Exclude<Action, null>) {
    if (next.type !== "personal-receipts" && !requireEditable()) return;
    setAction(next);
  }

  useEffect(() => {
    const quickAction=window.sessionStorage.getItem("dmp_finance_quick_action");
    if(quickAction!=="extra")return;
    window.sessionStorage.removeItem("dmp_finance_quick_action");
    setTab("extras");
    setAction({type:"extra-create"});
  }, []);

  function voiceCategoryKey(label:string) {
    return normalizeFinanceName(label);
  }

  function learnedVoiceCategory(label:string) {
    try {
      const raw=window.localStorage.getItem("dmp_finance_voice_categories");
      const map=raw?JSON.parse(raw) as Record<string,string>:{};
      const learned=map[voiceCategoryKey(label)]||"";
      return learned&&data.categories.includes(learned)?learned:"";
    } catch {
      return "";
    }
  }

  function rememberVoiceCategory(label:string,category:string) {
    try {
      const raw=window.localStorage.getItem("dmp_finance_voice_categories");
      const map=raw?JSON.parse(raw) as Record<string,string>:{};
      map[voiceCategoryKey(label)]=category;
      window.localStorage.setItem("dmp_finance_voice_categories",JSON.stringify(map));
    } catch {}
  }

  function addVoiceCategory() {
    if(!voicePreview||voicePreview.kind!=="extra"||!requireEditable())return;
    const name=window.prompt("Nome da nova categoria:")?.trim();
    if(!name)return;
    dispatch({type:"CATEGORY_CREATE",name,competence});
    setVoicePreview(current=>current&&current.kind==="extra"?{...current,category:name}:current);
  }

  function startVoice() {
    if (!requireEditable()) return;
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      window.alert("O reconhecimento de voz não está disponível neste navegador.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = "pt-BR";
    recognition.interimResults = false;
    recognition.continuous = false;
    recognition.onresult = (event: any) => {
      const text = event.results?.[0]?.[0]?.transcript || "";
      setVoiceText(text);
      const parsed=parseFinanceVoice(text, summary.personal, summary.expenses);
      if(parsed?.kind==="extra"){
        const learned=learnedVoiceCategory(parsed.label);
        setVoicePreview(learned?{...parsed,category:learned}:parsed);
      }else{
        setVoicePreview(parsed);
      }
    };
    recognition.onerror = () => window.alert("Não consegui entender. Tente novamente.");
    recognition.start();
  }

  useEffect(()=>{
    if(window.sessionStorage.getItem("dmp_finance_voice_start")!=="1")return;
    window.sessionStorage.removeItem("dmp_finance_voice_start");
    const timer=window.setTimeout(()=>startVoice(),350);
    return()=>window.clearTimeout(timer);
  },[]);

  function confirmVoice() {
    if (!voicePreview || !requireEditable()) return;
    const preview = voicePreview;
    if (preview.kind === "extra") {
      if (findDuplicateExtra(data, competence, today(), preview.label, preview.amount)) {
        window.alert("Esse gasto já parece estar lançado hoje. Nada foi duplicado.");
        return;
      }
      const category=preview.category || "Outros";
      dispatch({ type: "EXTRA_CREATE", competence, date: today(), description: preview.label, category, amount: preview.amount });
      rememberVoiceCategory(preview.label,category);
    } else if (preview.kind === "ds") {
      dispatch({ type: "DS_RECEIPT_ADD", competence, date: today(), amount: preview.amount, sourceName: "DS", note: "Lançado por voz" });
    } else if (preview.kind === "ranking") {
      dispatch({ type: "RANKING_SET", competence, amount: preview.amount });
    } else if (preview.kind === "card" && preview.expenseId) {
      const card = summary.expenses.find(item => item.id === preview.expenseId);
      if (card) dispatch({ type: "EXPENSE_UPDATE", id: card.id, name: card.name, dueDay: card.dueDay, expectedAmount: preview.amount, kind: card.kind, installmentCurrent: card.installmentCurrent, installmentTotal: card.installmentTotal });
    } else if (preview.kind === "expense" && preview.expenseId) {
      const expense = summary.expenses.find(item => item.id === preview.expenseId);
      if (expense) {
        if (findDuplicateExpensePayment(expense, today(), preview.amount)) {
          window.alert("Esse pagamento já parece estar registrado hoje. Nada foi duplicado.");
          return;
        }
        dispatch({ type: "EXPENSE_PAYMENT_ADD", expenseId: expense.id, date: today(), amount: preview.amount, note: "Lançado por voz" });
      }
    } else if (preview.kind === "personal" && preview.invoiceId) {
      const invoice = summary.personal.find(item => item.id === preview.invoiceId);
      if (invoice) {
        if (findDuplicatePersonalPayment(invoice, today(), preview.amount)) {
          window.alert("Esse recebimento já parece estar registrado hoje. Nada foi duplicado.");
          return;
        }
        dispatch({ type: "PERSONAL_PAYMENT_ADD", invoiceId: invoice.id, date: today(), amount: preview.amount, note: "Lançado por voz" });
      }
    }
    setVoiceText("");
    setVoicePreview(null);
  }

  const recent = useMemo(() => {
    const rows: { id: string; date: string; label: string; amount: number; direction: "IN" | "OUT" }[] = [];
    summary.personal.forEach(invoice => invoice.payments.forEach(payment => rows.push({ id: payment.id, date: payment.date, label: pixDisplayLabel(payment.mercadoPago,`${invoice.studentName} · Personal`), amount: payment.amount, direction: "IN" })));
    summary.receipts.forEach(receipt => rows.push({ id: receipt.id, date: receipt.date || `${competence}-01`, label: receipt.mercadoPago ? `${pixDisplayLabel(receipt.mercadoPago,receipt.sourceName||"Recebimento DS")} · DS` : receipt.sourceName ? `${receipt.sourceName} · DS` : "Recebimento DS", amount: receipt.amount, direction: "IN" }));
    summary.returns.forEach(payment => rows.push({ id: payment.id, date: payment.date, label: "Devolução para DS", amount: payment.amount, direction: "OUT" }));
    summary.expenses.forEach(expense => expense.payments.forEach(payment => rows.push({ id: payment.id, date: payment.date, label: expense.name, amount: payment.amount, direction: "OUT" })));
    summary.extras.forEach(extra => rows.push({ id: extra.id, date: extra.date, label: extra.description, amount: extra.amount, direction: "OUT" }));
    return rows.sort((a, b) => b.date.localeCompare(a.date)).slice(0, 10);
  }, [summary, competence]);

  function closeCompetence(createNext: boolean) {
    const warnings = [
      pendencies.personalOpen ? `${pendencies.personalOpen} mensalidades de Personal em aberto` : "",
      summary.expenses.filter(item => item.expectedAmount > 0 && expenseStatus(item) !== "PAID").length ? `${summary.expenses.filter(item => item.expectedAmount > 0 && expenseStatus(item) !== "PAID").length} contas em aberto` : "",
      summary.dsBalance > 0 ? `${money.format(summary.dsBalance)} ainda a receber da DS` : summary.dsBalance < 0 ? `${money.format(Math.abs(summary.dsBalance))} ainda a devolver para a DS` : "",
      pendencies.cardsMissing ? `${pendencies.cardsMissing} cartões sem valor de fatura` : "",
      pendencies.rankingMissing ? "ranking DS ainda não informado" : "",
    ].filter(Boolean);
    const suffix = warnings.length ? `\n\nPendências atuais:\n• ${warnings.join("\n• ")}\n\nO fechamento continuará guardando essas informações.` : "";
    const next = nextCompetence(competence);
    const message = createNext
      ? `Fechar ${competenceLabel(competence)} e abrir ${competenceLabel(next)}?${suffix}`
      : `Fechar ${competenceLabel(competence)}?${suffix}`;
    if (!window.confirm(message)) return;
    dispatch({ type: "CLOSE_COMPETENCE", competence, createNext });
    if (createNext) setTab("summary");
  }

  function reopenCompetence() {
    if (!window.confirm(`Reabrir ${competenceLabel(competence)} para edição?`)) return;
    dispatch({ type: "REOPEN_COMPETENCE", competence });
  }

  function createNextCompetence() {
    const next = nextCompetence(competence);
    if (!data.competences[next] && !window.confirm(`Criar ${competenceLabel(next)} copiando mensalidades, Kids, contas recorrentes e parcelamentos ainda ativos?`)) return;
    dispatch({ type: "CREATE_NEXT_COMPETENCE", fromCompetence: competence });
    setTab("summary");
  }

  function downloadReport() {
    const csv = financeReportCsv(data, competence);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `DMP_Financeiro_${competence}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  }

  return (
    <PixPayerProvider revision={financeCloudRevision} disabled={!loaded||!cloudWritable||syncing||!payerMetadataReady} onSavingChange={setPayerSaving} onSaved={async()=>{const cloud=await fetchFinanceCloud(financeSeedAugust2026);if(!cloud)throw new Error("Não foi possível recarregar o Financeiro.");const next={...cloud,currentCompetence:data.currentCompetence};setData(next);saveFinanceData(next);setFinanceCloudRevision(value=>value+1);}}>
    <>
      <header className={`dashboard-topbar ${styles.topbar} ${tab === "summary" ? styles.approvedTopbar : ""}`}>
        <div>
          <p className="dashboard-eyebrow">Gestão financeira</p>
          <h1>Financeiro</h1>
          <p>{competenceLabel(competence)} · <strong>{competenceStatusLabel(data.competences[competence]?.status)}</strong> · {syncing ? "sincronizando..." : cloudWritable ? "nuvem ativa" : "backup local"}</p>
        </div>
        <div className={styles.topActions}>
          <label className={styles.competencePicker}>
            <span>Competência</span>
            <select value={competence} onChange={event => dispatch({ type: "SWITCH_COMPETENCE", competence: event.target.value })}>
              {competences.map(item => <option key={item} value={item}>{competenceLabel(item)}</option>)}
            </select>
          </label>
        </div>
      </header>

      <section className={`dashboard-content ${styles.content}`}>
        {undoDeletion ? <div className={styles.undoStrip}><span>Exclusão realizada.</span><button onClick={undoLastDeletion}>Desfazer</button></div> : null}
        <nav className={styles.tabs}>
          {([
            ["summary", "Resumo"], ["mercado-pago", "Mercado Pago"], ["personal", "Personal"], ["ds", "DS Tênis"],
            ["expenses", "Despesas"], ["extras", "Gastos extras"],
            ["closing", "Fechamento"], ["reports", "Relatórios"],
          ] as [Tab, string][]).map(([key, label]) => (
            <button key={key} className={tab === key ? styles.activeTab : ""} onClick={() => setTab(key)}>{label}</button>
          ))}
        </nav>

        {!editable ? <section className={styles.closedBanner}><strong>🔒 {competenceLabel(competence)} está fechada.</strong><span>Os dados estão em modo somente leitura. Para corrigir algo, use Reabrir na aba Fechamento.</span></section> : null}

        {voiceText ? (
          <section className={`panel ${styles.voicePreview} ${voicePreview?.kind==="extra"?styles.voiceExtraPreview:""}`}>
            <div><span className="muted">Você disse</span><strong>“{voiceText}”</strong></div>
            {voicePreview?.kind==="extra" ? <div className={styles.voiceExtraFields}>
              <label>Estabelecimento / descrição<input value={voicePreview.label} onChange={event=>setVoicePreview(current=>current&&current.kind==="extra"?{...current,label:event.target.value}:current)} /></label>
              <label>Valor<input inputMode="decimal" value={String(voicePreview.amount).replace(".",",")} onChange={event=>{const amount=parseMoney(event.target.value);setVoicePreview(current=>current&&current.kind==="extra"&&amount!==null?{...current,amount}:current);}} /></label>
              <label>Categoria<select value={voicePreview.category||"Outros"} onChange={event=>setVoicePreview(current=>current&&current.kind==="extra"?{...current,category:event.target.value}:current)}>{data.categories.map(item=><option key={item}>{item}</option>)}</select></label>
              <button type="button" className="secondary" onClick={addVoiceCategory}>+ Categoria</button>
            </div> : voicePreview ? <div><span className="muted">Vou registrar</span><strong>{voicePreview.label} · {money.format(voicePreview.amount)}</strong></div> : <div><strong>Não ficou claro.</strong><span className="muted">Tente uma frase mais específica.</span></div>}
            <div className={styles.inlineActions}>
              <button className="secondary" onClick={() => { setVoiceText(""); setVoicePreview(null); }}>Cancelar</button>
              {voicePreview ? <button className="primary" onClick={confirmVoice}>Confirmar</button> : null}
            </div>
          </section>
        ) : null}

        {tab === "summary" ? (
          <>
            <FinanceSummaryView summary={summary} mercadoPagoBalance={mercadoPagoBalance} onOpen={setTab} onFilter={(next,target)=>{setListFilter(next);setTab(target);}} />

        <div className={styles.quickActions}>
          <button className={`secondary ${styles.launchButton}`} onClick={() => openAction({ type: "extra-create" })}>+ Lançar</button>
          <FinanceDeviceTrust onRevoked={onTrustRevoked} />
          <button className="secondary" onClick={() => setTab("personal")}>Receber personal</button>
          <button className="secondary" onClick={() => setTab("expenses")}>Pagar conta</button>
          <button className="secondary" onClick={() => openAction({ type: "ds-receipt" })}>Recebimento DS</button>
          <button className="secondary" onClick={() => openAction({ type: "extra-create" })}>Gasto extra</button>
        </div>

            <section className="panel">
              <div className="panel-head"><div><h2>Movimentações recentes</h2><p className="muted">Seu extrato interno do Financeiro.</p></div></div>
              <div className={styles.list}>{recent.length ? recent.map(item => <div className={`${styles.row} ${styles.staticRow}`} key={item.id}><span><strong>{item.label}</strong><PixPayerEditButton recordId={item.id}/><small>{formatDate(item.date)}</small></span><strong className={item.direction === "IN" ? styles.inValue : styles.outValue}>{item.direction === "IN" ? "+ " : "− "}{money.format(item.amount)}</strong></div>) : <Empty text="Nenhuma movimentação registrada nesta competência." />}</div>
            </section>
          </>
        ) : null}

        {tab !== "summary" ? (
        <div className={styles.quickActions}>
          <button className={`secondary ${styles.launchButton}`} onClick={() => openAction({ type: "extra-create" })}>+ Lançar</button>
          <FinanceDeviceTrust onRevoked={onTrustRevoked} />
          <button className="secondary" onClick={() => setTab("personal")}>Receber personal</button>
          <button className="secondary" onClick={() => setTab("expenses")}>Pagar conta</button>
          <button className="secondary" onClick={() => openAction({ type: "ds-receipt" })}>Recebimento DS</button>
          <button className="secondary" onClick={() => openAction({ type: "extra-create" })}>Gasto extra</button>
        </div>
        ) : null}

        {tab === "personal" ? (
          <section className="panel">
            <div className="panel-head"><div><h2>Personal · {competenceLabel(competence)}</h2><p className="muted">{money.format(summary.personalReceived)} recebidos de {money.format(summary.personalExpected)} previstos.{personalAudit?" · "+personalAudit.linked+" vinculados ao cadastro"+(personalAudit.ambiguous?" · "+personalAudit.ambiguous+" pendência(s) para conferência":"")+(personalAudit.unmatchedInvoices?" · "+personalAudit.unmatchedInvoices+" lançamento(s) sem aluno correspondente":""):""}</p></div><button className="primary" disabled={!editable} onClick={() => openAction({ type: "personal-create" })}>+ Mensalidade manual</button></div>
            <FilterBar value={listFilter} onChange={setListFilter} />
            <div className={styles.list}>
              {summary.personal.filter(invoice => matchesFilter(invoiceStatus(invoice), listFilter)).sort(compareDueDay).map(invoice => {
                const received = paid(invoice.payments); const missing = remaining(invoice.expectedAmount, invoice.payments); const status = invoiceStatus(invoice);
                return <div className={styles.rowShell} key={invoice.id}><button className={`${styles.row} ${styles.rowMain}`} disabled={!editable} onClick={() => openAction({ type: "personal-payment", invoice })}><span><strong>{invoice.studentName}</strong><small>Vence dia {invoice.dueDay} · {statusLabel(status)}{invoice.payments.length ? ` · ${invoice.payments.length} recebimento${invoice.payments.length > 1 ? "s" : ""}` : ""}</small></span><span className={styles.right}><strong>{money.format(invoice.expectedAmount)}</strong><small className={missing ? styles.openText : styles.paidText}>{missing ? `${money.format(missing)} falta` : `✓ ${money.format(received)} recebido`}</small></span></button><PersonalManageButton editable={editable} invoice={invoice} className={styles.manageButton} onManage={() => openAction({ type: invoice.profileManaged ? "personal-receipts" : "personal-edit", invoice })} /></div>;
              })}
            </div>
          </section>
        ) : null}

        {tab === "ds" ? (
          <div className="finance-ds-single">
            <section className="panel">
              <div className="panel-head"><div><h2>Acerto DS Tênis</h2><p className="muted">Saldo recalculado automaticamente.</p></div><div className={styles.inlineActions}><button className="secondary" disabled={!editable} onClick={() => openAction({ type: "ranking" })}>Editar ranking</button><button className="secondary" disabled={!editable} onClick={() => openAction({ type: "events" })}>Editar eventos</button></div></div>
              {competence === "2026-08" && summary.ranking === 6500 ? <div className={styles.importNote}><strong>Conferência da planilha</strong><span>O Resumo DS informa Ranking de R$ 6.500,00. Outro quadro da planilha mostra R$ 7.000,00. O DMP está usando R$ 6.500,00; altere aqui se necessário.</span></div> : null}
              <div className={styles.calc}><Calc label="Kids bruto" value={summary.kidsGross} />{summary.kidsCarryoverTotal>0?<Calc label="Incluído de pendências anteriores" value={summary.kidsCarryoverTotal}/>:null}<Calc label={`Sua parte (${Math.round(data.dsPercent * 100)}%)`} value={summary.kidsNet} /><Calc label="Ranking" value={summary.ranking} /><Calc label="Eventos" value={summary.events} /><Calc label="Acerto do mês" value={summary.dsSettlement} strong /><DsOpeningBalanceRow balance={summary.dsOpeningBalance} className={styles.calcRow}/><Calc label="Recebido da DS" value={summary.dsReceived} />{summary.dsReturned>0?<Calc label="Devolvido para DS" value={summary.dsReturned}/>:null}<Calc label={summary.dsBalance >= 0 ? "A receber da DS" : "A devolver para DS"} value={Math.abs(summary.dsBalance)} strong /></div>
              <button className={`primary ${styles.fullButton}`} disabled={!editable} onClick={() => openAction({ type: "ds-receipt" })}>+ Registrar recebimento DS</button>
              <button className={`secondary ${styles.fullButton}`} disabled={!editable || summary.dsBalance>=0} onClick={() => openAction({ type: "ds-return" })}>+ Registrar devolução para DS</button>
              <DsOpeningBalanceEditButton editable={editable} className={`secondary ${styles.fullButton}`} onEdit={() => openAction({ type: "ds-opening-balance" })}/>
              <div className={styles.receiptList}>{summary.receipts.length ? summary.receipts.map(receipt => <div key={receipt.id} className={styles.receipt}><span>{pixDisplayLabel(receipt.mercadoPago,receipt.sourceName || "DS")}<small>{receipt.date ? formatDate(receipt.date) : "Data não informada na planilha"}</small></span><div className={styles.receiptActions}><strong>{money.format(receipt.amount)}</strong><PixPayerEditButton recordId={receipt.id}/><button disabled={!editable} onClick={() => { if (window.confirm(`Excluir recebimento de ${money.format(receipt.amount)} da DS?`)) dispatch({ type: "DS_RECEIPT_DELETE", competence, receiptId: receipt.id }); }}>Excluir</button></div></div>) : <Empty text="Nenhum recebimento da DS registrado." />}</div>
              <div className={styles.receiptList}>{summary.returns.length ? summary.returns.map(payment => <div key={payment.id} className={styles.receipt}><span>Devolução para DS<small>{formatDate(payment.date)}{payment.note?` · ${payment.note}`:""}</small></span><div className={styles.receiptActions}><strong>{money.format(payment.amount)}</strong><button disabled={!editable} onClick={() => { if (window.confirm(`Excluir devolução de ${money.format(payment.amount)} para a DS?`)) dispatch({ type: "DS_RETURN_DELETE", competence, returnId: payment.id }); }}>Excluir</button></div></div>) : null}</div>
              <div className={styles.importNote}><strong>🔴 Pendências trazidas de meses anteriores</strong><span>Você escolhe somente quem deve entrar nesta competência. Esses valores entram no Kids bruto deste mês e não seguem automaticamente para o próximo.</span></div>
              <button className={`secondary ${styles.fullButton}`} disabled={!editable || !Object.keys(data.competences).some(item=>item<competence)} onClick={() => openAction({ type: "carry-create" })}>+ Trazer pendência</button>
              <div className={styles.receiptList}>{summary.kidsCarryovers.length ? summary.kidsCarryovers.slice().sort((a,b)=>a.studentName.localeCompare(b.studentName,"pt-BR")).map(item => <div key={item.id} className={styles.receipt}><span><strong>{item.studentName}</strong><small>Veio de {competenceLabel(item.originCompetence)} · {carryoverKindLabel(item.kind)}{item.note?` · ${item.note}`:""}</small></span><div className={styles.receiptActions}><strong className={styles.outValue}>{money.format(item.amount)}</strong><button disabled={!editable} onClick={() => openAction({type:"carry-edit",carry:item})}>Editar</button></div></div>) : <span className="muted">Nenhuma pendência trazida para este mês.</span>}</div>
            </section>
            <section className="panel">
              <div className="panel-head"><div><h2>Alunos Kids</h2><p className="muted">{summary.kids.length} registros válidos · {money.format(summary.kidsGross)} bruto.{kidsAudit?.excluded?` · ${kidsAudit.excluded} registro(s) antigo(s) preservado(s) fora da soma.`:""}{kidsAudit?.legacyIncluded?` · ${kidsAudit.legacyIncluded} registro(s) ainda sem vínculo.`:""}</p></div></div>
              <div className={`${styles.list} ${styles.scrollList}`}>{summary.kids.slice().sort((a,b)=>a.studentName.localeCompare(b.studentName,"pt-BR")).map(kid => <div className={styles.rowShell} key={kid.id}><div className={`${styles.row} ${styles.staticRow} ${styles.rowMain}`}><span><strong><FinanceCategoryDot category={kid.tennisCategory}/>{kid.studentName}</strong><small>{kid.installmentCurrent && kid.installmentTotal ? `${kid.installmentCurrent}/${kid.installmentTotal}` : kid.installmentTotal ? `${kid.installmentTotal} parcelas · atual a configurar` : "Parcelas a configurar"}</small></span><strong>{money.format(kid.amount)}</strong></div><button className={styles.manageButton} disabled={!editable} onClick={() => openAction({ type: "kid-edit", kid })}>Editar</button></div>)}</div>
            </section>
          </div>
        ) : null}

        {tab === "expenses" ? <ExpenseList title="Despesas" items={summary.expenses} filter={listFilter} setFilter={setListFilter} editable={editable} onCreate={() => openAction({ type: "expense-create" })} onPay={expense => openAction({ type: "expense-payment", expense })} onEdit={expense => openAction({ type: "expense-edit", expense })} /> : null}

        {tab === "extras" ? (
          <div className={styles.twoColWide}>
            <section className="panel">
              <div className="panel-head"><div><h2>Gastos extras</h2><p className="muted">{summary.extras.length} lançamentos · {money.format(summary.extrasTotal)} realizados.</p></div></div>
              <div className={`${styles.list} ${styles.scrollList}`}>{[...summary.extras].sort((a, b) => b.date.localeCompare(a.date)).map(extra => <div className={styles.rowShell} key={extra.id}><div className={`${styles.row} ${styles.staticRow} ${styles.rowMain}`}><span><strong>{extra.description}</strong><small>{formatDate(extra.date)} · {extra.category}{extra.paymentMethod ? ` · ${extra.paymentMethod}` : ""}</small></span><strong>{money.format(extra.amount)}</strong></div><button className={styles.manageButton} disabled={!editable} onClick={() => openAction({ type: "extra-edit", extra })}>Editar</button></div>)}</div>
            </section>
            <section className="panel">
              <div className="panel-head"><div><h2>Panorama dos gastos</h2><p className="muted">Visão rápida dos gastos extras de {competenceLabel(competence)}.</p></div></div>
              <div className={styles.extraPanoramaTotal}><span>Total no mês</span><strong>{money.format(summary.extrasTotal)}</strong></div>
              <div className={styles.extraCategoryBreakdown}>{categoryTotals(data, competence).length ? categoryTotals(data, competence).map(item => { const pct=summary.extrasTotal?Math.round((item.value/summary.extrasTotal)*100):0; return <div key={item.label}><span><strong>{item.label}</strong><small>{pct}% do total</small></span><b>{money.format(item.value)}</b></div>; }) : <Empty text="Sem gastos extras nesta competência." />}</div>
              <div className={styles.extraQuickAdd}><div><strong>Incluir gasto</strong><small>Abra o lançamento rápido e registre valor, categoria e forma de pagamento.</small></div><button className="primary" disabled={!editable} onClick={() => openAction({ type: "extra-create" })}>+ Incluir gasto</button></div>
              <div className={styles.categoryManagerCard}>
                <div className={styles.categoryManagerHead}>
                  <div>
                    <strong>Categorias de gastos</strong>
                    <small>Crie, renomeie ou arquive categorias sem perder os lançamentos antigos.</small>
                  </div>
                  <button className="secondary" type="button" disabled={!editable} onClick={() => openAction({ type: "category-create" })}>+ Nova categoria</button>
                </div>
                <div className={styles.categoryManagerList}>
                  {data.categories.map(category => {
                    const usageCount = data.extraExpenses.filter(item => item.category === category).length;
                    const used = usageCount > 0;
                    return (
                      <div className={styles.categoryManagerRow} key={category}>
                        <div className={styles.categoryManagerName}>
                          <strong>{category}</strong>
                          <small>{used ? usageCount + " lançamento" + (usageCount === 1 ? "" : "s") + " no histórico" : "Ainda não utilizada"}</small>
                        </div>
                        <div className={styles.categoryManagerActions}>
                          <button
                            type="button"
                            disabled={!editable}
                            onClick={() => {
                              const nextName = window.prompt("Novo nome para “" + category + "”:", category)?.trim();
                              if (!nextName || nextName === category) return;
                              const duplicate = data.categories.some(item => item !== category && item.toLocaleLowerCase("pt-BR") === nextName.toLocaleLowerCase("pt-BR"));
                              if (duplicate) {
                                window.alert("Já existe uma categoria com esse nome.");
                                return;
                              }
                              if (used && !window.confirm("Renomear “" + category + "” para “" + nextName + "”? Os " + usageCount + " lançamentos antigos também passarão a usar o novo nome.")) return;
                              dispatch({ type: "CATEGORY_RENAME", oldName: category, newName: nextName, competence });
                            }}
                          >
                            Renomear
                          </button>
                          <button
                            className={styles.categoryManagerDanger}
                            type="button"
                            disabled={!editable}
                            onClick={() => {
                              if (used) {
                                if (!window.confirm("Arquivar “" + category + "”? Ela deixará de aparecer nos novos lançamentos. Os " + usageCount + " lançamentos já registrados continuarão no histórico.")) return;
                                dispatch({ type: "CATEGORY_ARCHIVE", name: category, competence });
                                return;
                              }
                              if (!window.confirm("Excluir a categoria “" + category + "”?")) return;
                              dispatch({ type: "CATEGORY_DELETE", name: category, competence });
                            }}
                          >
                            {used ? "Arquivar" : "Excluir"}
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </section>
          </div>
        ) : null}

        {tab === "mercado-pago" ? <MercadoPagoTestPage financeRefreshKey={financeCloudRevision} onFinanceChanged={refreshFinanceAfterMercadoPago} onBalanceChanged={setMercadoPagoBalance} /> : null}

        {tab === "closing" ? <ClosingTab data={data} competence={competence} summary={summary} pendencies={pendencies} editable={editable} onClose={closeCompetence} onReopen={reopenCompetence} onCreateNext={createNextCompetence} onSwitch={value => dispatch({ type: "SWITCH_COMPETENCE", competence: value })} /> : null}

        {tab === "reports" ? <ReportsTab data={data} competence={competence} onDownload={downloadReport} /> : null}
      </section>

      {action ? <FinanceActionModal action={action} data={data} competence={competence} kidsStudentOptions={kidsStudentOptions} onClose={() => setAction(null)} dispatch={dispatch} /> : null}
    </>
    </PixPayerProvider>
  );
}

function FinanceActionModal({ action, data, competence, kidsStudentOptions, onClose, dispatch }: { action: Exclude<Action, null>; data: FinanceData; competence: string; kidsStudentOptions:Array<{id:string;name:string}>; onClose: () => void; dispatch: (command: FinanceCommand) => void }) {
  const invoiceId = action.type === "personal-edit" || action.type === "personal-payment" || action.type === "personal-receipts" ? action.invoice.id : null;
  const invoice = data.personalInvoices.find(item => item.id === invoiceId) || null;
  const expense = action.type === "expense-edit" || action.type === "expense-detail" || action.type === "expense-payment" || action.type === "card-value" ? action.expense : null;
  const kid = action.type === "kid-edit" ? action.kid : null;
  const carry = action.type === "carry-edit" ? action.carry : null;
  const extra = action.type === "extra-edit" ? action.extra : null;
  const defaultKind: FinanceExpenseKind = action.type === "expense-create" ? action.kind || "RECURRING" : expense?.kind || "RECURRING";
  const isPayment = action.type === "personal-payment" || action.type === "expense-payment";
  const initialAmount = action.type === "personal-payment" && invoice ? remaining(invoice.expectedAmount, invoice.payments)
    : action.type === "expense-payment" && expense ? remaining(expense.expectedAmount, expense.payments)
      : action.type === "card-value" && expense ? expense.expectedAmount
        : action.type === "ranking" ? data.rankingByCompetence[competence] || 0
          : action.type === "events" ? data.eventsByCompetence?.[competence] || 0
          : kid ? kid.amount
            : carry ? carry.amount
              : extra ? extra.amount
              : action.type === "personal-edit" && invoice ? invoice.expectedAmount
                : action.type === "expense-edit" && expense ? expense.expectedAmount
                  : action.type === "ds-return" ? Math.max(0, -financeSummary(data, competence).dsBalance)
                    : action.type === "ds-opening-balance" ? Math.abs(financeSummary(data, competence).dsOpeningBalance)
                    : 0;

  const [dsOpeningDirection,setDsOpeningDirection] = useState<"RECEIVE"|"RETURN">(financeSummary(data,competence).dsOpeningBalance<0?"RETURN":"RECEIVE");
  const [amount, setAmount] = useState(initialAmount ? String(initialAmount).replace(".", ",") : "");
  const [date, setDate] = useState(extra?.date || today());
  const [name, setName] = useState(invoice?.studentName || kid?.studentName || expense?.name || "");
  const [description, setDescription] = useState(extra?.description || "");
  const [category, setCategory] = useState(extra?.category || data.categories[0] || "Outros");
  const categoryOptions = data.categories.includes(category) ? data.categories : [category, ...data.categories]; // DMP_CATEGORIAS_GASTOS_V4_20260916
  const [method, setMethod] = useState(extra?.paymentMethod || "");
  const [dueDay, setDueDay] = useState(String(invoice?.dueDay || kid?.dueDay || expense?.dueDay || 10));
  const [expenseStart,setExpenseStart]=useState(competence);
  const [deleteScope,setDeleteScope]=useState<"CURRENT"|"CURRENT_AND_FUTURE">("CURRENT");
  const [kind, setKind] = useState<FinanceExpenseKind>(defaultKind);
  const [installmentCurrent, setInstallmentCurrent] = useState(String(kid?.installmentCurrent || expense?.installmentCurrent || ""));
  const [installmentTotal, setInstallmentTotal] = useState(String(kid?.installmentTotal || expense?.installmentTotal || ""));
  const [sourceName, setSourceName] = useState("DS");
  const [note, setNote] = useState("");
  const [expenseNote,setExpenseNote]=useState(expense?.note||"");
  const [paymentLink,setPaymentLink]=useState(expense?.paymentLink||"");
  const [newCategory, setNewCategory] = useState("");
  const [kidBillingMode,setKidBillingMode]=useState<"SINGLE"|"INSTALLMENT"|"RECURRING">(kid?.billingMode||"RECURRING");
  const [kidCategory,setKidCategory]=useState<"RED"|"ORANGE"|"GREEN"|null>(kid?.tennisCategory||null);
  const originOptions=Object.keys(data.competences).filter(item=>item<competence).sort().reverse();
  const fallbackCarryName=carry?.studentName||"";
  const [carryStudentId,setCarryStudentId]=useState(carry?.studentId||"");
  const [carryStudentName,setCarryStudentName]=useState(fallbackCarryName);
  const [carryOrigin,setCarryOrigin]=useState(carry?.originCompetence||originOptions[0]||"");
  const [carryKind,setCarryKind]=useState<FinanceCarryoverKind>(carry?.kind||"SINGLE");
  function carrySourceAmount(studentId:string,studentName:string,origin:string,kind:FinanceCarryoverKind){
    if(!origin||(!studentId&&!studentName.trim()))return null;
    const expectedMode=kind==="SINGLE"?"SINGLE":kind==="INSTALLMENT"?"INSTALLMENT":kind==="MONTHLY"?"RECURRING":null;
    const usedSources=new Set((data.carriedPendencies||[]).filter(item=>item.id!==carry?.id&&item.sourceEntryId).map(item=>item.sourceEntryId as string));
    const matches=data.dsKids.filter(item=>item.competence===origin&&!item.excludedFromTotals&&!usedSources.has(item.id)&&((studentId&&item.studentId===studentId)||normalizeFinanceName(item.studentName)===normalizeFinanceName(studentName)));
    const source=(expectedMode?matches.find(item=>item.billingMode===expectedMode):null)||matches[0]||null;
    return source?.amount??null;
  }
  function pullCarryAmount(studentId:string,studentName:string,origin:string,kind:FinanceCarryoverKind){
    const found=carrySourceAmount(studentId,studentName,origin,kind);
    if(found!==null)setAmount(String(found).replace(".",","));
  }

  function numericAmount() { return parseMoney(amount); }
  function validDay() { return Math.min(31, Math.max(1, Number(dueDay) || 1)); }
  function optNumber(value: string) { const parsed = Number(value); return value && Number.isFinite(parsed) && parsed > 0 ? parsed : null; }

  function submit(event: FormEvent) {
    event.preventDefault();
    if (action.type === "personal-receipts") return;
    const numeric = numericAmount();

    if (action.type === "category-create") {
      if (!newCategory.trim()) return;
      dispatch({ type: "CATEGORY_CREATE", name: newCategory, competence });
      onClose(); return;
    }

    if (action.type === "personal-create" || action.type === "personal-edit") {
      if (!name.trim() || numeric === null || numeric < 0) return;
      if (action.type === "personal-create") dispatch({ type: "PERSONAL_CREATE", competence, studentName: name, dueDay: validDay(), expectedAmount: numeric });
      else dispatch({ type: "PERSONAL_UPDATE", id: action.invoice.id, studentName: name, dueDay: validDay(), expectedAmount: numeric });
      onClose(); return;
    }

    if (action.type === "personal-payment") {
      if (numeric === null || numeric <= 0) return;
      if (findDuplicatePersonalPayment(action.invoice, date, numeric)) { window.alert("Esse recebimento já está registrado com a mesma data e valor."); return; }
      dispatch({ type: "PERSONAL_PAYMENT_ADD", invoiceId: action.invoice.id, date, amount: numeric, note });
      onClose(); return;
    }

    if (action.type === "expense-create" || action.type === "expense-edit") {
      if (!name.trim() || numeric === null || numeric < 0) return;
      const current = kind==="INSTALLMENT"?(optNumber(installmentCurrent)||1):null; const total = kind==="INSTALLMENT"?optNumber(installmentTotal):null;
      if(kind==="INSTALLMENT" && (!total || !Number.isInteger(total) || !current || !Number.isInteger(current) || current>total)){window.alert("Confira a parcela atual e o total de parcelas.");return;}
      if(action.type==="expense-create" && (!isValidExpenseCompetence(expenseStart) || !isCompetenceEditable(data,expenseStart))){window.alert("Escolha um mês/ano de início válido e aberto.");return;}
      if(action.type==="expense-create" && !data.competences[expenseStart]) {
        const from=Object.keys(data.competences).filter(value=>value<expenseStart).sort().at(-1);
        const distance=from?(Number(expenseStart.slice(0,4))-Number(from.slice(0,4)))*12+Number(expenseStart.slice(5))-Number(from.slice(5)):121;
        if(distance>120){window.alert("Selecione uma competência existente ou um início até 120 meses após a última competência disponível.");return;}
      }
      if (action.type === "expense-create") dispatch({ type: "EXPENSE_CREATE", competence, startCompetence:expenseStart, name, dueDay: validDay(), expectedAmount: numeric, kind, installmentCurrent: current, installmentTotal: total, note: expenseNote, paymentLink });
      else dispatch({ type: "EXPENSE_UPDATE", id: action.expense.id, name, dueDay: validDay(), expectedAmount: numeric, kind, installmentCurrent: current, installmentTotal: total, note: expenseNote, paymentLink });
      onClose(); return;
    }

    if (action.type === "expense-payment") {
      if (numeric === null || numeric <= 0) return;
      if (findDuplicateExpensePayment(action.expense, date, numeric)) { window.alert("Esse pagamento já está registrado com a mesma data e valor."); return; }
      dispatch({ type: "EXPENSE_PAYMENT_ADD", expenseId: action.expense.id, date, amount: numeric, note });
      onClose(); return;
    }

    if (action.type === "card-value") {
      if (numeric === null || numeric < 0) return;
      dispatch({ type: "EXPENSE_UPDATE", id: action.expense.id, name: action.expense.name, dueDay: action.expense.dueDay, expectedAmount: numeric, kind: action.expense.kind, installmentCurrent: action.expense.installmentCurrent, installmentTotal: action.expense.installmentTotal, note: action.expense.note, paymentLink: action.expense.paymentLink });
      onClose(); return;
    }

    if (action.type === "ranking") {
      if (numeric === null || numeric < 0) return;
      dispatch({ type: "RANKING_SET", competence, amount: numeric }); onClose(); return;
    }

    if (action.type === "ds-receipt") {
      if (numeric === null || numeric <= 0) return;
      dispatch({ type: "DS_RECEIPT_ADD", competence, date, amount: numeric, sourceName, note });
      onClose(); return;
    }

    if (action.type === "events") {
      if (numeric === null || numeric < 0) return;
      dispatch({ type: "EVENTS_SET", competence, amount: numeric }); onClose(); return;
    }

    if (action.type === "ds-return") {
      if (numeric === null || numeric <= 0) return;
      const available = Math.max(0, -financeSummary(data, competence).dsBalance);
      if (numeric > available + .005) { window.alert(`A devolução não pode ultrapassar o saldo de ${money.format(available)} devido à DS.`); return; }
      dispatch({ type: "DS_RETURN_ADD", competence, date, amount: numeric, note });
      onClose(); return;
    }

    if (action.type === "ds-opening-balance") {
      if (numeric === null || numeric < 0 || !note.trim()) return;
      const sign = dsOpeningDirection === "RETURN" ? -1 : 1;
      dispatch({ type: "DS_OPENING_BALANCE_SET", competence, balance: numeric * sign, note });
      onClose(); return;
    }

    if (action.type === "kid-create" || action.type === "kid-edit") {
      if (!name.trim() || numeric === null || numeric < 0) return;
      const total = kidBillingMode==="INSTALLMENT"?optNumber(installmentTotal):null;
      const current = kidBillingMode==="INSTALLMENT"?(optNumber(installmentCurrent)||1):null;
      if(kidBillingMode==="INSTALLMENT"&&!total)return;
      const payload={studentName:name,amount:numeric,dueDay:validDay(),billingMode:kidBillingMode,tennisCategory:kidCategory,installmentCurrent:current,installmentTotal:total};
      if (action.type === "kid-create") dispatch({ type: "DS_KID_CREATE", competence, ...payload });
      else dispatch({ type: "DS_KID_UPDATE", id: action.kid.id, ...payload });
      onClose(); return;
    }

    if (action.type === "carry-create" || action.type === "carry-edit") {
      if (numeric === null || numeric <= 0 || !carryOrigin || carryOrigin >= competence || !carryStudentName.trim()) return;
      const duplicate=(data.carriedPendencies||[]).some(item=>item.id!==carry?.id&&item.competence===competence&&item.originCompetence===carryOrigin&&((carryStudentId&&item.studentId===carryStudentId)||normalizeFinanceName(item.studentName)===normalizeFinanceName(carryStudentName)));
      if(duplicate){window.alert("Essa pendência já foi trazida para esta competência.");return;}
      const expectedMode=carryKind==="SINGLE"?"SINGLE":carryKind==="INSTALLMENT"?"INSTALLMENT":carryKind==="MONTHLY"?"RECURRING":null;
      const usedSources=new Set((data.carriedPendencies||[]).filter(item=>item.id!==carry?.id&&item.sourceEntryId).map(item=>item.sourceEntryId as string));
      const sourceCandidates=data.dsKids.filter(item=>item.competence===carryOrigin&&!item.excludedFromTotals&&!usedSources.has(item.id)&&((carryStudentId&&item.studentId===carryStudentId)||normalizeFinanceName(item.studentName)===normalizeFinanceName(carryStudentName)));
      const exactSources=sourceCandidates.filter(item=>Math.abs(item.amount-numeric)<.005);
      const source=exactSources.find(item=>!expectedMode||item.billingMode===expectedMode)||exactSources[0]||null;
      const payload={originCompetence:carryOrigin,studentId:carryStudentId||source?.studentId||null,studentName:carryStudentName,amount:numeric,kind:carryKind,note,sourceEntryId:source?.id||null};
      if(action.type==="carry-create")dispatch({type:"CARRYOVER_CREATE",competence,...payload});
      else dispatch({type:"CARRYOVER_UPDATE",id:action.carry.id,...payload});
      onClose(); return;
    }

    if (action.type === "extra-create" || action.type === "extra-edit") {
      if (numeric === null || numeric <= 0 || !description.trim()) return;
      const finalCategory = category || suggestCategory(description);
      if (findDuplicateExtra(data, competence, date, description, numeric, extra?.id)) { window.alert("Esse gasto já parece estar lançado com a mesma data, descrição e valor."); return; }
      if (action.type === "extra-create") dispatch({ type: "EXTRA_CREATE", competence, date, description, category: finalCategory, paymentMethod: method, amount: numeric });
      else dispatch({ type: "EXTRA_UPDATE", id: action.extra.id, date, description, category: finalCategory, paymentMethod: method, amount: numeric });
      onClose(); return;
    }
  }

  const title = modalTitle(action);
  useEffect(() => {
    if(action.type !== "expense-create" && action.type !== "expense-edit" && action.type !== "personal-receipts") return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = previousOverflow; };
  }, [action.type]);
  const isInstallment = kind === "INSTALLMENT";

  return <div className={styles.modalBackdrop} onMouseDown={event => { if (event.currentTarget === event.target) onClose(); }}><form className={`${styles.modal} ${(action.type === "expense-create" || action.type === "expense-edit" || action.type === "personal-receipts") ? styles.expenseModal : ""} ${(action.type === "personal-edit" || action.type === "expense-edit" || action.type === "personal-receipts") ? styles.modalLarge : ""}`} onSubmit={submit}><div className={styles.modalHead}><div><span className="muted">Financeiro · {competenceLabel(competence)}</span><h2>{title}</h2></div><button type="button" className="text-button" onClick={onClose}>Fechar</button></div>
    <div className={styles.modalBody}>

    {action.type === "personal-create" || action.type === "personal-edit" ? <><label>Aluno<input value={name} onChange={event => setName(event.target.value)} autoFocus /></label><div className={styles.formGrid}><label>Mensalidade<input value={amount} onChange={event => setAmount(event.target.value)} placeholder="0,00" /></label><label>Vencimento (dia)<input type="number" min="1" max="31" value={dueDay} onChange={event => setDueDay(event.target.value)} /></label></div>{action.type === "personal-edit" ? <PaymentHistory title="Recebimentos registrados" className={styles.paymentHistory} payments={invoice?.payments || []} onDelete={payment => { if (window.confirm(`Excluir recebimento de ${money.format(payment.amount)} em ${formatDate(payment.date)}?`)) dispatch({ type: "PERSONAL_PAYMENT_DELETE", invoiceId: action.invoice.id, paymentId: payment.id }); }} /> : null}</> : null}

    {action.type === "personal-receipts" ? invoice ? <PersonalReceipts invoice={invoice} editable={isCompetenceEditable(data, invoice.competence)} classes={styles} onDelete={payment => {
      if (!isCompetenceEditable(data, invoice.competence)) return;
      if (window.confirm(`Excluir o recebimento de ${money.format(payment.amount)} de ${invoice.studentName} em ${formatDate(payment.date)}? Esta ação será registrada no histórico.`)) dispatch({ type: "PERSONAL_PAYMENT_DELETE", invoiceId: invoice.id, paymentId: payment.id });
    }} /> : <p>Mensalidade não encontrada.</p> : null}

    {action.type === "personal-payment" ? <><div className={styles.formGrid}><label>Valor recebido<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label><label>Data<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label></div><label>Observação<input value={note} onChange={event => setNote(event.target.value)} placeholder="Opcional" /></label><p className={styles.formHint}>Previsto {money.format(action.invoice.expectedAmount)} · já recebido {money.format(paid(action.invoice.payments))} · falta {money.format(remaining(action.invoice.expectedAmount, action.invoice.payments))}</p></> : null}

    {action.type === "expense-create" || action.type === "expense-edit" ? <><label>Conta / despesa<input value={name} onChange={event => setName(event.target.value)} autoFocus /></label><div className={styles.formGrid}><label>Valor previsto<input value={amount} onChange={event => setAmount(event.target.value)} placeholder="0,00" /></label><label>Vencimento (dia)<input type="number" min="1" max="31" value={dueDay} onChange={event => setDueDay(event.target.value)} /></label></div>{action.type==="expense-create"?<label>Mês/Ano de início<input type="month" value={expenseStart} min="2000-01" max="2199-12" required onChange={event=>setExpenseStart(event.target.value)}/><small>A primeira cobrança será nesta competência.</small></label>:null}<label>Tipo<select value={kind} onChange={event => setKind(event.target.value as FinanceExpenseKind)}><option value="RECURRING">Recorrente</option><option value="INSTALLMENT">Parcelamento</option><option value="CARD">Cartão</option><option value="VARIABLE">Variável / só este mês</option></select></label>{isInstallment ? <div className={styles.formGrid}><label>Parcela atual<input type="number" min="1" value={installmentCurrent} onChange={event => setInstallmentCurrent(event.target.value)} /></label><label>Total de parcelas<input type="number" min="1" value={installmentTotal} onChange={event => setInstallmentTotal(event.target.value)} /></label></div> : null}<label>Link para pagamento<input value={paymentLink} onChange={event=>setPaymentLink(event.target.value)} placeholder="https://... (opcional)" /></label><label>Observação da conta<textarea rows={2} value={expenseNote} onChange={event=>setExpenseNote(event.target.value)} placeholder="Opcional" /></label>{action.type === "expense-edit" ? <PaymentHistory title="Pagamentos registrados" className={styles.paymentHistory} payments={action.expense.payments} onDelete={payment => { if (window.confirm(`Excluir pagamento de ${money.format(payment.amount)} em ${formatDate(payment.date)}?`)) dispatch({ type: "EXPENSE_PAYMENT_DELETE", expenseId: action.expense.id, paymentId: payment.id }); }} /> : null}</> : null}

    {action.type === "expense-detail" ? <div className={styles.expenseDetail}><div className={styles.expenseDetailHero}><div><small>Conta</small><h2>{action.expense.name}</h2><span>Vence dia {action.expense.dueDay}</span></div><strong>{money.format(remaining(action.expense.expectedAmount,action.expense.payments))}</strong></div><dl><div><dt>Valor previsto</dt><dd>{money.format(action.expense.expectedAmount)}</dd></div><div><dt>Já pago</dt><dd>{money.format(paid(action.expense.payments))}</dd></div><div><dt>Status</dt><dd>{remaining(action.expense.expectedAmount,action.expense.payments)>0?"Em aberto":"Pago"}</dd></div></dl>{action.expense.note?<div className={styles.expenseDetailNote}><strong>Observação</strong><p>{action.expense.note}</p></div>:null}{action.expense.paymentLink?<a className={styles.paymentLinkButton} href={normalizePaymentUrl(action.expense.paymentLink)} target="_blank" rel="noreferrer">Abrir para pagar ↗</a>:<p className={styles.formHint}>Esta conta ainda não possui link de pagamento cadastrado.</p>}</div> : null}

    {action.type === "expense-payment" ? <><div className={styles.formGrid}><label>Valor pago<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label><label>Data<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label></div><label>Observação<input value={note} onChange={event => setNote(event.target.value)} placeholder="Opcional" /></label><p className={styles.formHint}>Previsto {money.format(action.expense.expectedAmount)} · já pago {money.format(paid(action.expense.payments))} · falta {money.format(remaining(action.expense.expectedAmount, action.expense.payments))}</p></> : null}

    {action.type === "card-value" ? <label>Valor da fatura<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label> : null}
    {action.type === "ranking" ? <label>Ranking do mês<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label> : null}
    {action.type === "events" ? <label>Eventos do mês<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label> : null}

    {action.type === "ds-receipt" ? <><div className={styles.formGrid}><label>Valor recebido<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label><label>Data<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label></div><label>Origem<input value={sourceName} onChange={event => setSourceName(event.target.value)} placeholder="DS" /></label><label>Observação<input value={note} onChange={event => setNote(event.target.value)} placeholder="Opcional" /></label></> : null}
    {action.type === "ds-return" ? <><div className={styles.formGrid}><label>Valor devolvido<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus /></label><label>Data<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label></div><label>Observação<input value={note} onChange={event => setNote(event.target.value)} placeholder="Ex.: devolução parcial" /></label></> : null}
    {action.type === "ds-opening-balance" ? <><label>Direção do saldo<select value={dsOpeningDirection} onChange={event=>setDsOpeningDirection(event.target.value as "RECEIVE"|"RETURN")}><option value="RECEIVE">A receber da DS</option><option value="RETURN">A devolver para DS</option></select></label><label>Novo valor<input value={amount} onChange={event => setAmount(event.target.value)} autoFocus placeholder="0,00" /></label><label>Motivo da alteração<input value={note} onChange={event => setNote(event.target.value)} placeholder="Obrigatório" required /></label></> : null}

    {action.type === "kid-create" || action.type === "kid-edit" ? <><label>Aluno Kids<input value={name} onChange={event => setName(event.target.value)} autoFocus /></label><div className={styles.formGrid}><label>Valor<input value={amount} onChange={event => setAmount(event.target.value)} /></label><label>Vencimento (dia)<input type="number" min="1" max="31" value={dueDay} onChange={event=>setDueDay(event.target.value)}/></label></div><label>Forma de cobrança<select value={kidBillingMode} onChange={event=>setKidBillingMode(event.target.value as typeof kidBillingMode)}><option value="SINGLE">Parcela única</option><option value="INSTALLMENT">Parcelado por quantidade de meses</option><option value="RECURRING">Recorrente sem término</option></select></label>{kidBillingMode==="INSTALLMENT"?<div className={styles.formGrid}><label>Parcela atual<input type="number" min="1" value={installmentCurrent||"1"} onChange={event=>setInstallmentCurrent(event.target.value)}/></label><label>Quantidade de parcelas<input type="number" min="1" value={installmentTotal} onChange={event=>setInstallmentTotal(event.target.value)}/></label></div>:null}<fieldset className={styles.categoryPicker}><legend>Categoria DS Tênis</legend>{([null,"RED","ORANGE","GREEN"] as const).map(value=><button type="button" key={value||"NONE"} className={kidCategory===value?styles.categorySelected:""} onClick={()=>setKidCategory(value)}>{value===null?"Sem categoria":value==="RED"?"🔴 Vermelha":value==="ORANGE"?"🟠 Laranja":"🟢 Verde"}</button>)}</fieldset></> : null}

    {action.type === "carry-create" || action.type === "carry-edit" ? <><label>Criança<select value={carryStudentId} onChange={event=>{const id=event.target.value;const option=kidsStudentOptions.find(item=>item.id===id);const name=option?.name||"";setCarryStudentId(id);setCarryStudentName(name);pullCarryAmount(id,name,carryOrigin,carryKind);}} autoFocus><option value="">Selecione...</option>{kidsStudentOptions.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{(!kidsStudentOptions.length||(carryStudentId&&!kidsStudentOptions.some(item=>item.id===carryStudentId)))?<label>Nome da criança<input value={carryStudentName} onChange={event=>{const name=event.target.value;setCarryStudentName(name);}} onBlur={()=>pullCarryAmount(carryStudentId,carryStudentName,carryOrigin,carryKind)} placeholder="Digite o nome" /></label>:null}<div className={styles.formGrid}><label>Competência de origem<select value={carryOrigin} onChange={event=>{const origin=event.target.value;setCarryOrigin(origin);pullCarryAmount(carryStudentId,carryStudentName,origin,carryKind);}}>{originOptions.map(item=><option key={item} value={item}>{competenceLabel(item)}</option>)}</select></label><label>Valor<input value={amount} onChange={event=>setAmount(event.target.value)} placeholder="0,00" /><small>Preenchido automaticamente pela competência de origem quando encontrado; continua editável.</small></label></div><label>Tipo<select value={carryKind} onChange={event=>{const kind=event.target.value as FinanceCarryoverKind;setCarryKind(kind);pullCarryAmount(carryStudentId,carryStudentName,carryOrigin,kind);}}><option value="SINGLE">Uma parcela</option><option value="MONTHLY">Mensalidade</option><option value="INSTALLMENT">Parcela</option><option value="OTHER">Outro</option></select></label><label>Observação<input value={note} onChange={event=>setNote(event.target.value)} placeholder="Opcional" /></label><p className={styles.formHint}>Entra somente em {competenceLabel(competence)}. Não será renovada no mês seguinte. Se houver lançamento correspondente na origem, ele deixa de contar lá enquanto esta pendência existir.</p></> : null}

    {action.type === "extra-create" || action.type === "extra-edit" ? <><label>Descrição<input value={description} onChange={event => { setDescription(event.target.value); if (!category) setCategory(suggestCategory(event.target.value)); }} placeholder="Ex.: Padaria" autoFocus /></label><div className={styles.formGrid}><label>Valor<input value={amount} onChange={event => setAmount(event.target.value)} placeholder="0,00" /></label><label>Data<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label></div><div className={styles.formGrid}><label>Categoria<select value={category} onChange={event => setCategory(event.target.value)}>{categoryOptions.map(item => <option key={item}>{item}</option>)}</select></label><label>Forma de pagamento<input value={method} onChange={event => setMethod(event.target.value)} placeholder="Pix, Débito..." /></label></div></> : null}

    {action.type === "category-create" ? <label>Nova categoria<input value={newCategory} onChange={event => setNewCategory(event.target.value)} autoFocus placeholder="Ex.: Saúde" /></label> : null}

    {action.type === "expense-edit" ? <div className={styles.deleteScope}>
        {action.expense.kind!=="VARIABLE" && action.expense.seriesId?<label>Excluir<select value={deleteScope} onChange={event=>setDeleteScope(event.target.value as typeof deleteScope)}><option value="CURRENT">Somente esta parcela/competência</option><option value="CURRENT_AND_FUTURE">Esta e as próximas</option></select></label>:null}
        {!action.expense.seriesId && action.expense.kind!=="VARIABLE"?<small>Conta antiga sem vínculo de série: exclusão somente desta competência.</small>:null}
    </div> : null}
    </div>
    <div className={styles.modalActions}>
      {action.type === "expense-detail" ? <><button type="button" className="secondary" onClick={onClose}>Fechar</button><span className={styles.modalSpacer}/>{remaining(action.expense.expectedAmount,action.expense.payments)>0?<button type="button" className="primary" onClick={()=>{const open=remaining(action.expense.expectedAmount,action.expense.payments);if(window.confirm(`Marcar ${action.expense.name} como paga no valor de ${money.format(open)}?`)){dispatch({type:"EXPENSE_PAYMENT_ADD",expenseId:action.expense.id,date:today(),amount:open,note:"Pagamento marcado pela tela de vencimentos."});onClose();}}}>Marcar como paga</button>:null}</> : null}
      {action.type === "personal-edit" ? <button type="button" className={styles.dangerButton} onClick={() => { if (window.confirm(`Excluir a mensalidade de ${action.invoice.studentName}?`)) { dispatch({ type: "PERSONAL_DELETE", id: action.invoice.id }); onClose(); } }}>Excluir mensalidade</button> : null}
      {action.type === "expense-edit" ? <div className={styles.expenseDeleteAction}>
        <button type="button" className={styles.dangerButton} onClick={()=>{
          if(deleteScope==="CURRENT" && action.expense.payments.length){window.alert("Esta despesa possui pagamentos. A exclusão foi bloqueada para preservar o histórico.");return;}
          const description=deleteScope==="CURRENT"?"somente esta competência":"esta e as próximas cobranças da mesma série";
          if(window.confirm(`Excluir ${action.expense.name}: ${description}?\n\nPagamentos registrados e competências fechadas serão preservados.`)){dispatch({type:"EXPENSE_DELETE",id:action.expense.id,scope:deleteScope});onClose();}
        }}>Excluir despesa</button>
      </div> : null}
      {action.type === "kid-edit" ? <button type="button" className={styles.dangerButton} onClick={() => { if (window.confirm(`Excluir ${action.kid.studentName} da lista Kids deste mês?`)) { dispatch({ type: "DS_KID_DELETE", id: action.kid.id }); onClose(); } }}>Excluir Kids</button> : null}
      {action.type === "carry-edit" ? <button type="button" className={styles.dangerButton} onClick={() => { if (window.confirm(`Excluir a pendência trazida de ${action.carry.studentName}?`)) { dispatch({ type: "CARRYOVER_DELETE", id: action.carry.id }); onClose(); } }}>Excluir pendência</button> : null}
      {action.type === "extra-edit" ? <button type="button" className={styles.dangerButton} onClick={() => { if (window.confirm(`Excluir o gasto “${action.extra.description}”?`)) { dispatch({ type: "EXTRA_DELETE", id: action.extra.id }); onClose(); } }}>Excluir gasto</button> : null}
      {action.type === "personal-receipts" ? <button type="button" className="secondary" onClick={onClose}>Fechar</button> : null}
      {action.type !== "expense-detail" && action.type !== "personal-receipts" ? <><span className={styles.modalSpacer} /><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Salvar</button></> : null}
    </div>
  </form></div>;
}

function ExpenseList({ title, items, filter, setFilter, editable, onCreate, onPay, onEdit }: { title: string; items: FinanceExpense[]; filter: Filter; setFilter: (value: Filter) => void; editable: boolean; onCreate: () => void; onPay: (expense: FinanceExpense) => void; onEdit: (expense: FinanceExpense) => void }) {
  const filtered = items.filter(item => matchesFilter(expenseStatus(item), filter)).sort(compareDueDay);
  return <section className="panel"><div className="panel-head"><div><h2>{title}</h2><p className="muted">Contas recorrentes, parcelamentos e despesas do mês.</p></div><button className="primary" disabled={!editable} onClick={onCreate}>+ Nova conta</button></div><FilterBar value={filter} onChange={setFilter} /><div className={styles.list}>{filtered.length ? filtered.map(expense => { const missing = remaining(expense.expectedAmount, expense.payments); return <div className={styles.rowShell} key={expense.id}><button className={`${styles.row} ${styles.rowMain}`} disabled={!editable} onClick={() => onPay(expense)}><span><strong>{expense.name}</strong><small>{expense.installmentCurrent && expense.installmentTotal ? `${expense.installmentCurrent}/${expense.installmentTotal} · ` : ""}vence dia {expense.dueDay} · {expenseKindLabel(expense.kind)} · {statusLabel(expenseStatus(expense))}</small></span><span className={styles.right}><strong>{money.format(expense.expectedAmount)}</strong><small className={missing ? styles.openText : styles.paidText}>{missing ? `${money.format(missing)} falta` : "✓ Pago"}</small></span></button><button className={styles.manageButton} disabled={!editable} onClick={() => onEdit(expense)}>Editar</button></div>; }) : <Empty text="Nenhuma conta neste filtro." />}</div></section>;
}

function ClosingTab({ data, competence, summary, pendencies, editable, onClose, onReopen, onCreateNext, onSwitch }: { data: FinanceData; competence: string; summary: ReturnType<typeof financeSummary>; pendencies: ReturnType<typeof financialPendencies>; editable: boolean; onClose: (createNext: boolean) => void; onReopen: () => void; onCreateNext: () => void; onSwitch: (value: string) => void }) {
  const next = nextCompetence(competence);
  const monthHistory = (data.history || []).filter(item => item.competence === competence).slice().sort((a, b) => b.occurredAt.localeCompare(a.occurredAt));
  const accountsOpen = summary.expenses.filter(item => item.expectedAmount > 0 && expenseStatus(item) !== "PAID").length;
  const monthChecked = !pendencies.personalOpen && !accountsOpen && Math.abs(summary.dsBalance) < .01 && !pendencies.cardsMissing && !pendencies.rankingMissing;
  return <div className={styles.twoCol}>
    <section className="panel">
      <div className="panel-head"><div><h2>Fechamento · {competenceLabel(competence)}</h2><p className="muted">Congele o mês e prepare a competência seguinte.</p></div></div>
      <div className={styles.closingStatus}><span>Status atual</span><strong>{competenceStatusLabel(data.competences[competence]?.status)}</strong></div>
      <div className={monthChecked?styles.monthCheckOk:styles.monthCheckWarning}><strong>{monthChecked?"✓ Conferência do mês concluída":"⚠ Conferência do mês requer atenção"}</strong><span>{monthChecked?"Personal, despesas e DS estão conferidos.":"Revise os itens indicados abaixo antes de fechar."}</span></div>
      <div className={styles.calc}><Calc label="Resultado realizado" value={summary.realizedResult} strong /><Calc label="Saldo projetado" value={summary.projectedResult} /><Calc label="Personal em aberto" value={summary.personalOpen} /><Calc label="Saldo DS" value={summary.dsBalance} /><Calc label="Contas a pagar" value={summary.payable} /></div>
      <div className={styles.checkList}><span className={!pendencies.personalOpen ? styles.checkOk : ""}>● {pendencies.personalOpen ? `${pendencies.personalOpen} mensalidades de Personal em aberto` : "Personal conferido"}</span><span className={!accountsOpen ? styles.checkOk : ""}>● {accountsOpen ? `${accountsOpen} contas ainda em aberto` : "Despesas conferidas"}</span><span className={Math.abs(summary.dsBalance) < .01 ? styles.checkOk : ""}>● {Math.abs(summary.dsBalance) < .01 ? "DS acertada" : `${money.format(Math.abs(summary.dsBalance))} ${summary.dsBalance >= 0 ? "a receber da DS" : "a devolver para DS"}`}</span><span className={!pendencies.cardsMissing ? styles.checkOk : ""}>● {pendencies.cardsMissing ? `${pendencies.cardsMissing} cartões sem valor de fatura` : "Faturas dos cartões conferidas"}</span><span className={!pendencies.rankingMissing ? styles.checkOk : ""}>● {pendencies.rankingMissing ? "Ranking DS ainda não informado" : "Ranking DS conferido"}</span></div>
      {editable ? <div className={styles.closingActions}><button className="secondary" onClick={() => onClose(false)}>Fechar somente este mês</button><button className="primary" onClick={() => onClose(true)}>Fechar e abrir {competenceLabel(next)}</button><button className="text-button" onClick={onCreateNext}>{data.competences[next] ? `Ir para ${competenceLabel(next)}` : `Criar ${competenceLabel(next)} sem fechar agora`}</button></div> : <div className={styles.closingActions}><button className="primary" onClick={onReopen}>Reabrir competência</button>{data.competences[next] ? <button className="secondary" onClick={() => onSwitch(next)}>Ir para {competenceLabel(next)}</button> : <button className="secondary" onClick={onCreateNext}>Criar {competenceLabel(next)}</button>}</div>}
    </section>
    <section className="panel">
      <div className="panel-head"><div><h2>Histórico do mês</h2><p className="muted">Alterações importantes ficam registradas automaticamente.</p></div></div>
      <div className={`${styles.historyList} ${styles.scrollList}`}>{monthHistory.length ? monthHistory.map(item => <div className={styles.historyItem} key={item.id}><span><strong>{pixDisplayLabel(item.mercadoPago,item.description)}</strong><PixPayerEditButton recordId={item.id}/><small>{formatDateTime(item.occurredAt)}</small></span>{typeof item.amount === "number" ? <strong>{money.format(item.amount)}</strong> : null}</div>) : <Empty text="O histórico começará a registrar as alterações feitas a partir desta versão." />}</div>
    </section>
