for(const width of [1920,1600,1440,1280])test('mini-cards '+width+'px: padding, altura, largura e grade uniformes',()=>{for(const sheets of [[globals,home],[home,globals]]){let expected;for(const cls of ['today-summary-card','month-closing-today-card']){const c=card(cls),inside=element('div',[],c),lines=element('span',['highlight-lines'],inside),tile=element('small',[],lines),d=cascade(sheets,tile,width),g=cascade(sheets,lines,width);assert.equal(g.gap,'12px');assert.equal(g['grid-auto-rows'],'minmax(132px,1fr)');assert.equal(d['min-height'],'132px');assert.equal(d.height,'auto');assert.equal(d.padding,'14px');assert.equal(d['border-radius'],'14px');assert.equal(d['white-space'],'normal');assert.equal(d['overflow-y'],'visible');const common=[d.padding,d['min-height'],d['font-size'],d['line-height'],d['border-radius']];if(expected)assert.deepEqual(common,expected);expected=common;}
const summary=cascade(sheets,card('today-summary-card'),width),monthly=cascade(sheets,card('month-closing-today-card'),width);assert.equal(summary.width,'calc(40% - 1.2px)');assert.equal(monthly.width,'calc(60% - 12.8px)');assert.equal(summary['grid-column'],'1/-1');assert.equal(monthly['grid-column'],'1/-1');assert.equal(summary['justify-self'],'start');assert.equal(monthly['justify-self'],'end');
// Calcula o espaço real disponível: 34px de borda/padding por painel, gap 12 por grade.
for(const available of [width,width-540,width-640]){const sw=available*.4-1.2,mw=available*.6-12.8;assert.ok(sw>0&&mw>0);assert.ok(Math.abs((sw-34-12)/2-(mw-34-24)/3)<1e-9);assert.ok(Math.abs(available-sw-mw-14)<1e-9);}}});
